vertexShader:
attribute vec2 aSeed; uniform float uTime; uniform float uScale; varying float vA; varying float vAge;
#include <fog_pars_vertex>
void main(){ float age = fract(aSeed.x + uTime * 0.045 + aSeed.y * 0.3); vAge = age;
  vec3 p = position + vec3(age * 14.0 + sin(age * 6.0 + aSeed.y * 9.0) * 1.5, age * 26.0, age * 5.0 + cos(age * 5.0 + aSeed.y * 7.0) * 1.2);   // up and away on the wind
  vec4 mvPosition = modelViewMatrix * vec4(p, 1.0); gl_Position = projectionMatrix * mvPosition; gl_PointSize = (3.0 + age * 15.0) * uScale / -mvPosition.z;
  vA = smoothstep(0.0, 0.08, age) * (1.0 - smoothstep(0.55, 1.0, age));
#include <fog_vertex>
}

fragmentShader:
uniform sampler2D map; varying float vA; varying float vAge;
#include <fog_pars_fragment>
void main(){ float a = texture2D(map, gl_PointCoord).a * vA * 0.42; vec3 c = mix(vec3(0.16, 0.12, 0.1), vec3(0.06, 0.065, 0.06), vAge);   // warm soot low (lit from the street), grey up high
  gl_FragColor = vec4(c, a);
#include <fog_fragment>
}
